#include<cstdio>
#include<algorithm>
#include<cmath>
using namespace std;const int N=200005;int n,m,B,a[N],tmp[N],tot,mxL[N],mxR[N],ans;int stkC[N],stkL[N],stkR[N],stkAns[N];int tag[N],fir[N],las[N],tStamp;struct Q{int l,r,id;}q[N];int res[N];void brute(int l,int r,int&ret){++tStamp;ret=0;for(int i=l;i<=r;++i){int c=a[i];if(tag[c]!=tStamp)tag[c]=tStamp,fir[c]=las[c]=i;else{las[c]=i;if(las[c]-fir[c]>ret)ret=las[c]-fir[c];}}}int main(){scanf("%d",&n);for(int i=0;i<n;++i)scanf("%d",&a[i]),tmp[i]=a[i];sort(tmp,tmp+n);tot=unique(tmp,tmp+n)-tmp;for(int i=0;i<n;++i)a[i]=lower_bound(tmp,tmp+tot,a[i])-tmp+1;scanf("%d",&m);for(int i=0;i<m;++i){scanf("%d%d",&q[i].l,&q[i].r);--q[i].l;--q[i].r;q[i].id=i;}B=max(1,(int)(n/sqrt(m)));sort(q,q+m,[](Q x,Q y){int bx=x.l/B,by=y.l/B;return bx!=by?bx<by:x.r<y.r;});for(int i=0;i<m;){int blk=q[i].l/B;int Rblk=min(n-1,(blk+1)*B-1);for(int j=1;j<=tot;++j)mxL[j]=n+1,mxR[j]=-1;ans=0;int curR=Rblk;while(i<m&&q[i].l/B==blk){if(q[i].r<=Rblk){brute(q[i].l,q[i].r,res[q[i].id]);}else{while(curR<q[i].r){++curR;int c=a[curR];if(curR<mxL[c])mxL[c]=curR;if(curR>mxR[c])mxR[c]=curR;if(mxR[c]-mxL[c]>ans)ans=mxR[c]-mxL[c];}int tmpL=Rblk+1,top=0;while(tmpL>q[i].l){--tmpL;int c=a[tmpL];stkC[top]=c;stkL[top]=mxL[c];stkR[top]=mxR[c];stkAns[top]=ans;++top;if(tmpL<mxL[c])mxL[c]=tmpL;if(tmpL>mxR[c])mxR[c]=tmpL;if(mxR[c]-mxL[c]>ans)ans=mxR[c]-mxL[c];}res[q[i].id]=ans;while(top--){mxL[stkC[top]]=stkL[top];mxR[stkC[top]]=stkR[top];ans=stkAns[top];}}++i;}}for(int i=0;i<m;++i)printf("%d\n",res[i]);return 0;}